function validate([root, targetSum]) {
  if (!Number.isInteger(targetSum) || targetSum < -1000 || targetSum > 1000) return 'targetSum is a whole number from -1000 to 1000.';
  if (root.length === 0) return null;
  if (root[0] === null) return 'Write an empty tree as [].';
  const values = root.filter(v => v !== null);
  if (values.length > 5000) return 'The tree has at most 5000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each node value is a whole number from -1000 to 1000.';
  let open = 1;
  for (const v of root) {
    if (open === 0) return 'Every value after the root needs a parent node.';
    open += v === null ? -1 : 1;
  }
  return null;
}

