function pathSum(root, targetSum) {
  const result = [];
  const path = [];

  function dfs(node, remaining) {
    if (!node) {
      return;
    }
    path.push(node.val);
    remaining -= node.val;
    if (!node.left && !node.right && remaining === 0) {
      result.push([...path]);
    }
    dfs(node.left, remaining);
    dfs(node.right, remaining);
    path.pop();
  }

  dfs(root, targetSum);
  return result;
}

