function pathSum(root, targetSum) {
  if (!root) return [];
  const found = [];
  const queue = [[root, [root.val]]];
  while (queue.length) {
    const [node, values] = queue.shift();
    if (!node.left && !node.right) {
      if (values.reduce((a, b) => a + b, 0) === targetSum) found.push(values);
      continue;
    }
    if (node.left) queue.push([node.left, [...values, node.left.val]]);
    if (node.right) queue.push([node.right, [...values, node.right.val]]);
  }
  return found;
}

