function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'small' && rand() < 0.08) return [[], pick(5) - 2];
  const count = size === 'large' ? 900 + pick(99) : 1 + pick(12);
  const span = size === 'large' ? (rand() < 0.5 ? 3 : 1000) : (rand() < 0.6 ? 3 : 10);
  const value = () => pick(2 * span + 1) - span;
  const deep = rand() < 0.3;
  const nodes = [{ val: value(), left: null, right: null }];
  while (nodes.length < count) {
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    const node = { val: value(), left: null, right: null };
    parent[side] = node;
    nodes.push(node);
  }
  // Most of the time aim the target at a real root-to-leaf path so that matches occur.
  let targetSum = value();
  if (rand() < 0.65) {
    targetSum = 0;
    let node = nodes[0];
    while (node) {
      targetSum += node.val;
      const kids = [node.left, node.right].filter(Boolean);
      node = kids.length ? kids[pick(kids.length)] : null;
    }
  }
  targetSum = Math.max(-1000, Math.min(1000, targetSum));
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out, targetSum];
}
